import 'package:flutter/material.dart';
import '../gateway/engine_gateway.dart';
import '../generated/torca_contract.dart';

class ConversationScreen extends StatefulWidget { const ConversationScreen({required this.gateway, required this.conversation, super.key}); final EngineGateway gateway; final ConversationDto conversation; @override State<ConversationScreen> createState() => _ConversationScreenState(); }
class _ConversationScreenState extends State<ConversationScreen> { final controller = TextEditingController(); @override void dispose() { controller.dispose(); super.dispose(); } @override Widget build(BuildContext context) => ValueListenableBuilder<AppSnapshotDto>(valueListenable: widget.gateway.snapshots, builder: (context, snapshot, _) { final messages = snapshot.messages.where((message) => message.conversationId == widget.conversation.id).toList(); return Scaffold(appBar: AppBar(title: const Text('Conversation')), body: Column(children: [Expanded(child: ListView.builder(itemCount: messages.length, itemBuilder: (_, index) => ListTile(title: Text(messages[index].body), subtitle: Text(messages[index].status)))), Padding(padding: const EdgeInsets.all(12), child: Row(children: [Expanded(child: TextField(controller: controller, decoration: const InputDecoration(labelText: 'Message'))), IconButton(icon: const Icon(Icons.send), onPressed: () { final body = controller.text; if (body.isEmpty) return; final id = DateTime.now().microsecondsSinceEpoch.toRadixString(16).padLeft(32, '0').substring(0, 32); widget.gateway.execute(QueueMessageCommandDto(messageIdHex: id, conversationIdHex: widget.conversation.id, body: body, atMs: DateTime.now().millisecondsSinceEpoch)); controller.clear(); })]))]); }); }
